document.addEventListener("click",function(e){const t=getComputedStyle(document.documentElement).getPropertyValue("--primary").trim();createParticles(e.clientX,e.clientY,t)});function createParticles(e,t,n){const s=12;for(let i=0;i<s;i++){const o=document.createElement("div");o.classList.add("click-particle"),document.body.appendChild(o);const c=(Math.random()-.5)*100,l=(Math.random()-.5)*100,a=Math.random()*6+4,r=Math.random()*520;o.style.backgroundColor=n,o.style.left=`${e}px`,o.style.top=`${t}px`,o.style.width=`${a}px`,o.style.height=`${a}px`,o.style.transform=`rotate(${r}deg)`;const d=o.animate([{transform:`translate(0, 0) rotate(0deg)`,opacity:1},{transform:`translate(${c}px, ${l}px) rotate(${r}deg)`,opacity:0}],{duration:800+Math.random()*200,easing:"cubic-bezier(0, .9, .57, 1)",fill:"forwards"});d.onfinish=()=>{o.remove()}}}